# Enumerate D4 translated template placements containing each demo seed set, using coordinates transcribed from grids.
def variants(S):
    out=set()
    for k in range(8):
        pts=[]
        for r,c in S:
            if k<4: x,y=r,c
            else: x,y=r,-c
            for _ in range(k%4): x,y=y,-x
            pts.append((x,y))
        mr=min(x for x,y in pts); mc=min(y for x,y in pts)
        out.add(frozenset((x-mr,y-mc) for x,y in pts))
    return out

