# Repeated motif and its alternate appearance in the demonstrations.
MOTIF_A = {(0, 2), (0, 3), (1, 0), (1, 1), (2, 2)}
MOTIF_B = {
    (0, 1), (0, 2), (0, 3),
    (1, 0), (1, 4),
    (2, 1),
    (3, 1), (3, 2),
}


def components(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    result = {}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 1 or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            cells = set(q)
            while q:
                x, y = q.pop()
                for nx, ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0 <= nx < h and 0 <= ny < w and (nx, ny) not in seen and grid[nx][ny] == color:
                        seen.add((nx, ny))
                        cells.add((nx, ny))
                        q.append((nx, ny))
            result.setdefault(color, []).append(cells)
    return result


def normalize(cells):
    mr = min(r for r, c in cells)
    mc = min(c for r, c in cells)
    return frozenset((r-mr, c-mc) for r, c in cells)


def orientations(shape):
    out = set()
    for reflected in (False, True):
        for rot in range(4):
            pts = []
            for r, c in shape:
                x, y = (r, -c) if reflected else (r, c)
                for _ in range(rot):
                    x, y = y, -x
                pts.append((x, y))
            mr, mc = min(x for x, y in pts), min(y for x, y in pts)
            out.add(frozenset((x-mr, y-mc) for x, y in pts))
    return out


def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    comps = components(grid)
    all_cells = set().union(*(set(c) for cs in comps.values() for c in cs)) if comps else set()
    known = (MOTIF_A, MOTIF_B)
    for color, objects in comps.items():
        for seed in objects:
            candidates = set()
            for motif in known:
                for shape in orientations(motif):
                    for sr, sc in seed:
                        for vr, vc in shape:
                            dr, dc = sr-vr, sc-vc
                            placed = frozenset((r+dr, c+dc) for r, c in shape)
                            if seed <= placed and all(0 <= r < h and 0 <= c < w for r, c in placed):
                                # Preserve observed cells and avoid overwriting unrelated objects.
                                added = placed - seed
                                if not (added & (all_cells - seed)):
                                    candidates.add(placed)
            if not candidates:
                continue
            # The intended motif placement is selected by adding the least total Manhattan
            # distance from new cells to the observed seed. This matches the compact, nearest
            # completion seen in the examples.
            def key(place):
                added = place - seed
                dist = sum(min(abs(r-x)+abs(c-y) for x, y in seed) for r, c in added)
                return (dist, max((min(abs(r-x)+abs(c-y) for x, y in seed) for r,c in added), default=0))
            chosen = min(candidates, key=key)
            for r, c in chosen:
                out[r][c] = color
    return out


